class Solution:
    def canFormArray(self, arr: List[int], pieces: List[List[int]]) -> bool:
        keys, ans = {}, []
        for piece in pieces:
            keys[piece[0]] = piece
        for a in arr:
            if a in keys:
                ans.extend(keys[a])
        return ''.join(map(str, arr)) == ''.join(map(str, ans))

from queue import deque

class Solution:
    def getMaximumGenerated(self, n: int) -> int:

        def arrgen(n):
            yield 0
            q = deque([1])
            while True:
                yield q[0]
                q.append(q[0])
                q.append(q[0]+q[1])
                q.popleft()

        g = arrgen(n)
        return max(next(g) for _ in range(n+1))

